  ?appearance wdt:P1303 ?show;
              wdt:P710 wd:Q5271104. # Paul Melba's Wikidata entity
  ?show wdt:P840 ?host.
  ?host wdt:P1128 ?hostedShowsCount.
  FILTER (?hostedShowsCount = 23)
} Limit 1

