SELECT ?company ?companyLabel ?terminus ?terminusLabel ?terminusLocation ?terminusCountyLabel WHERE {
  # Find the Quaker Ridge station on New York, Westchester and Boston Railway (or NYW&B)
  ?station rdfs:label "Quaker Ridge"@en .
  ?station wdt:P31 wd:Q55488 ;  # instance of: railway station
           wdt:P171* ?line .
  ?line rdfs:label ?lineLabel FILTER(CONTAINS(LCASE(?lineLabel), "new york westchester and boston")) .

  # Get the company operating or owning the station or line
  OPTIONAL { ?station wdt:P137 ?company . }
  OPTIONAL { ?line wdt:P137 ?company . }

  # Get the terminus station(s) of the company or line
  OPTIONAL {
    ?company wdt:P1039 ?terminus . # operator of terminus - if applicable
  }
  OPTIONAL {
    ?line wdt:P559 ?terminus . # terminus station for railway line
  }

  # Get location of the terminus
  OPTIONAL {
    ?terminus wdt:P131 ?terminusLocation .
    ?terminusLocation wdt:P131 ?terminusCounty .
  }
  # Get county of terminusLocation if not direct
  OPTIONAL {
    ?terminusLocation wdt:P131 ?terminusCounty .
  }

  # Labels
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }

  # Filter to specify main cities and counties
  FILTER(BOUND(?company))
  FILTER(BOUND(?terminus))
} LIMIT 10

# Additionally verify:
# - Is "New York city" located in Westchester County?
# SPARQL query for this:

SELECT ?nyc ?nycCounty WHERE {
  ?nyc rdfs:label "New York City"@en .
  ?nyc wdt:P31 wd:Q515 . # instance of city
  ?nyc wdt:P131 ?nycCounty .
  ?nycCounty wdt:P31 wd:Q5109 . # instance of county
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?station ?stationLabel ?location ?locationLabel ?owner ?ownerLabel WHERE {
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }

  # Find the entity for Quaker Ridge station
  ?station rdfs:label "Quaker Ridge"@en .
  ?station wdt:P31/wdt:P279* wd:Q55488 . # instance of railway station or subclass
  ?station wdt:P131 ?location .
  ?station wdt:P127 ?owner .

} LIMIT 10;

SELECT ?railwayCompany ?terminus ?terminusLabel ?terminusLocation ?terminusLocationLabel WHERE {
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }

  # Find the New York, Westchester and Boston Railway entity
  ?railwayCompany rdfs:label "New York, Westchester and Boston Railway"@en .

  # Find termini of this railway
  ?terminus wdt:P31/wdt:P279* wd:Q55488 ;
           wdt:P137 ?railwayCompany ;
           wdt:P termini ?railwayCompany .

  # Fetch location of terminus stations
  OPTIONAL {
    ?terminus wdt:P131 ?terminusLocation .
  }
} LIMIT 10;

SELECT ?place ?placeLabel ?county ?countyLabel WHERE {
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }

  # Check if New York City is located in Westchester County
  ?place rdfs:label "New York City"@en .
  ?place wdt:P131* ?county .
  ?county rdfs:label "Westchester County"@en .
} LIMIT 10;

# 1. Find the identity of "German Frank Sinatra" and their awards
SELECT ?artist ?artistLabel ?award ?awardLabel WHERE {
  ?artist rdfs:label ?artistName.
  FILTER(CONTAINS(LCASE(?artistName), "german frank sinatra"))
  OPTIONAL {
    ?artist wdt:P166 ?award.
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

# 2. Identify the Skinny Puppy band member linked to Rx (band)
SELECT ?member ?memberLabel WHERE {
  ?band rdfs:label "Rx"@en.
  ?member wdt:P136 wd:Q321917; # instance of musician/composer if needed
          wdt:P53 ?band.
  ?band wdt:P31 wd:Q215380; # instance of musical group
  ?member wdt:P1344 wd:Q212034.

  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

# 3. Fetch awards of the identified Skinny Puppy band member
SELECT ?member ?memberLabel ?award ?awardLabel WHERE {
  ?member rdfs:label ?memberLabel.
  FILTER (?member IN (SELECTed Skinny Puppy member from above))
  OPTIONAL {
    ?member wdt:P166 ?award.
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

# Alternatively, a combined query could be formulated upon identifying the artists.

# Query to retrieve awards received by Nivek Ogre and German Frank Sinatra, including counts and details.

SELECT ?person ?personLabel (COUNT(?award) AS ?awardCount) WHERE {
  VALUES ?person { wd:Q1640489 wd:Q6211913 } # Q1640489 = Nivek Ogre, Q6211913 = Frank Sinatra (to be replaced by German Frank Sinatra entity if available)
  ?award wdt:P166 ?person .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". ?person rdfs:label ?personLabel. }
}
GROUP BY ?person ?personLabel

# If "German Frank Sinatra" corresponds to a specific individual known under that moniker in Wikidata, use that entity ID, otherwise search for German singers with the nickname "Frank Sinatra" or under that alias.

# Additional query to identify the entity corresponding to "German Frank Sinatra":

SELECT ?person ?personLabel WHERE {
  ?person ?label "German Frank Sinatra"@en.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT ?entity ?entityLabel ?awardsCount WHERE {
  VALUES ?entityLabel {"Nivek Ogre" "German Frank Sinatra"}
  ?entity rdfs:label ?entityLabel.
  OPTIONAL {
    ?entity wdt:P166 ?award.
  }
  # Count number of distinct awards
  {
    SELECT ?entity (COUNT(DISTINCT ?award) AS ?awardsCount) WHERE {
      ?entity rdfs:label ?entityLabel.
      OPTIONAL { ?entity wdt:P166 ?award. }
    } GROUP BY ?entity
  }
} GROUP BY ?entity ?entityLabel ?awardsCount

LIMIT 2

SELECT ?publication ?publicationLabel ?frequency ?hallOfFame ?inductee ?inductionYear WHERE {
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }

  # Find the frequency of Bookmarks
  ?bookmarks wdt:P31 wd:Q667610;       # instance of publication
             rdfs:label "Bookmarks"@en;
             wdt:P2077 ?bookmarksFrequency. # publication frequency

  # Find other publications with Hall of Fame
  ?publication wdt:P31 wd:Q667610;  # instance of publication
               wdt:P2077 ?frequency;
               wdt:P1441 ?hallOfFame.         # has Hall of Fame

  # Hall of Fame information
  ?hallOfFame wdt:P31 wd:Q18500723.  # instance of hall of fame

  # Find if Keith Moon is an inductee and induction date
  ?inductee rdfs:label "Keith Moon"@en.
  ?hallOfFame wdt:P1346 ?inductee.    # award received by / inducted
  OPTIONAL {
    ?inductee p:P1346 ?stmt.
    ?stmt ps:P1346 ?hallOfFame;
          pq:P580 ?inductionStart.
  }

  # Filter for inductee date in the early 1980s (1980-1984)
  FILTER(!BOUND(?inductionStart) || YEAR(?inductionStart) >= 1980 && YEAR(?inductionStart) <= 1984)

  # Ensure the other publication is published more often than Bookmarks
  FILTER(?frequency > ?bookmarksFrequency)
} LIMIT 10

SELECT ?publication ?publicationLabel ?frequency WHERE {
  VALUES ?publicationLabel {"Bookmarks"}.
  ?publication rdfs:label ?publicationLabel@en.
  OPTIONAL { ?publication wdt:P31 ?type. }
  OPTIONAL { ?publication wdt:P580 ?publicationStartDate. }
  OPTIONAL { ?publication wdt:P828 ?subject. }
  OPTIONAL { ?publication wdt:P2071 ?frequencyValue. }
  OPTIONAL { ?publication wdt:P1545 ?frequencyString. }
  OPTIONAL { ?publication wdt:P31 ?publicationType. }
  OPTIONAL { ?publication p:P31 ?statement. ?statement ps:P31 ?publicationType. }
  OPTIONAL {
    ?publication wdt:P2093 ?publisherName.
  }
} 

SELECT ?otherPublication ?otherPublicationLabel ?otherFrequency WHERE {
  ?otherPublication rdfs:label ?otherPublicationLabel.
  FILTER (?otherPublicationLabel != "Bookmarks")
  OPTIONAL { ?otherPublication wdt:P2071 ?otherFrequencyValue. }
  OPTIONAL { ?otherPublication wdt:P1545 ?otherFrequencyString. }
}

SELECT ?hallOfFame ?hallOfFameLabel ?inductee ?inductionDate WHERE {
  ?hallOfFame rdfs:label ?hallOfFameLabel.
  FILTER(CONTAINS(LCASE(?hallOfFameLabel), "hall of fame"))
  ?inductee wdt:P166 ?hallOfFame.
  ?inductee rdfs:label "Keith Moon"@en.
  OPTIONAL { ?inductee p:P166 ?honorStatement.
             ?honorStatement ps:P166 ?hallOfFame;
                           pq:P580 ?inductionDate. }
  FILTER(?inductionDate >= "1980-01-01"^^xsd:date && ?inductionDate < "1985-01-01"^^xsd:date)
}

SELECT ?candlelightRedAlbumCount ?uniqueSignalAlbumCount WHERE {
  {
    SELECT (COUNT(?album) AS ?candlelightRedAlbumCount) WHERE {
      ?album a dbo:Album ;
             dbo:artist dbr:Candlelight_Red .
    }
  }
  {
    SELECT (COUNT(?album) AS ?uniqueSignalAlbumCount) WHERE {
      ?album a dbo:Album ;
             dbo:artist ?uniqueSignalBand .
      ?uniqueSignalBand dbo:alias dbr:One_Unique_Signal .
    }
  }
}

SELECT ?candlelightRedAlbumCount ?uniqueSignalAlbumCount WHERE {
  {
    SELECT (COUNT(?album) AS ?candlelightRedAlbumCount) WHERE {
      ?album a dbo:Album ;
             dbo:artist dbr:Candlelight_Red .
    }
  }
  {
    SELECT (COUNT(?album) AS ?uniqueSignalAlbumCount) WHERE {
      ?album a dbo:Album ;
             dbo:artist ?uniqueSignalBand .
      ?uniqueSignalBand dbo:alias dbr:One_Unique_Signal .
    }
  }
}

