SELECT ?actor WHERE {
  ?wonderWomanFilm wdt:P31 wd:Q11424;  # instance of film
                    rdfs:label "Wonder Woman"@en;
                    wdt:P577 ?wwReleaseDate.
  FILTER(YEAR(?wwReleaseDate) = 2017)

  ?actor wdt:P161 ?wonderWomanFilm.  # cast member of Wonder Woman

  ?fargoShow wdt:P31 wd:Q5398426;  # instance of a television series
             rdfs:label "Fargo"@en;
             wdt:P577 ?fargoPremiereDate.

  ?anomalisaFilm wdt:P31 wd:Q11424; # instance of film
                 rdfs:label "Anomalisa"@en;
                 wdt:P577 ?anomalisaReleaseDate.

  ?actor wdt:P161 ?anomalisaFilm.

  FILTER(?anomalisaReleaseDate > ?fargoPremiereDate)
}

